function installScroll15(){const d=$('.dialog'),body=$('#dialogbody');d.classList.add('scroll15');let start=null,moved=false;body.addEventListener('pointerdown',e=>{if(e.target.closest('input,select,textarea'))return;start={id:e.pointerId,y:e.clientY,scroll:body.scrollTop};moved=false;});body.addEventListener('pointermove',e=>{if(!start||start.id!==e.pointerId)return;const scale=$('#game').getBoundingClientRect().width/960,dy=(e.clientY-start.y)/scale;if(Math.abs(dy)>6){moved=true;body.scrollTop=start.scroll-dy;}});body.addEventListener('click',e=>{if(moved){e.preventDefault();e.stopImmediatePropagation();moved=false;}},true);document.addEventListener('pointerup',()=>{start=null;});body.addEventListener('pointercancel',()=>start=null);const nav=document.createElement('div');nav.id='scrollnav';nav.innerHTML='<button aria-label="Scroll up">▲</button><span>DESLIZAR</span><button aria-label="Scroll down">▼</button>';d.insertBefore(nav,$('#dialogbuttons'));nav.firstElementChild.onclick=()=>body.scrollBy({top:-200,behavior:'smooth'});nav.lastElementChild.onclick=()=>body.scrollBy({top:200,behavior:'smooth'});}

