const mineIntroText25=[L23('Max: Los reportes de mutaciones vienen de esta mina. El Corrodium afecta a humanos; vigila tu vida.','Max: Mutation reports lead to this mine. Corrodium affects humans; watch your health.','Max: Os relatos de mutações levam a esta mina. Corrodium afeta humanos; cuide da vida.','Max: Mutasyon haberleri bu madenden geliyor. Corrodium insanları etkiler; canına dikkat et.'),L23('Ten: Materia Gris puede entrar en las tuberías. Repara ocho generadores para iluminar el camino.','Ten: Grey Matter fits inside the pipes. Repair eight generators to light the route.','Ten: Massa Cinzenta cabe nos tubos. Conserte oito geradores para iluminar o caminho.','Ten: Gri Madde borulara sığabilir. Yolu aydınlatmak için sekiz jeneratörü onar.'),L23('Max: XLR8 esquivará los láseres y Diamante reflejará la energía. Si aparece una momia, acércate para escanearla.','Max: XLR8 can dodge lasers and Diamondhead can reflect energy. If a mummy appears, approach to scan it.','Max: XLR8 desvia dos lasers e Diamante reflete energia. Se uma múmia aparecer, aproxime-se para escanear.','Max: XLR8 lazerlerden kaçar; Elmas Kafa enerjiyi yansıtır. Bir mumya çıkarsa taramak için yaklaş.')];
const cinemaDrawBase25=drawCinema;drawCinema=function(){if(!cinematic||cinematic.mode!=='movie'||!['mineBrief25','benmomia','cannonbolt'].includes(cinematic.id))return cinemaDrawBase25();const screen=$('#cinemaworld'),w=innerWidth,h=innerHeight,dpr=quality17==='low'?1:Math.min(2,devicePixelRatio||1);if(screen.width!==Math.round(w*dpr)||screen.height!==Math.round(h*dpr)){screen.width=Math.round(w*dpr);screen.height=Math.round(h*dpr);}const c=screen.getContext('2d');c.setTransform(dpr,0,0,dpr,0,0);c.imageSmoothingEnabled=false;const t=cinematic.time,id=cinematic.id;c.fillStyle='#04150a';c.fillRect(0,0,w,h);if(id==='cannonbolt'){const ix=Math.min(7,Math.floor(t/12.9*8)),f=FRAMES25.cannonCinema25.table[ix],scale=Math.max(w/f[2],h/f[3]),fw=f[2]*scale,fh=f[3]*scale;c.drawImage(art.cannonCinema25,...f,(w-fw)/2,(h-fh)/2,fw,fh);}else if(id==='mineBrief25'){const part=Math.min(2,Math.floor(t/5));mineTile25(c,4,0,0,w,h);c.fillStyle='#070817a8';c.fillRect(0,0,w,h);cineFrame22(c,spriteInfo(3),0,w*.28,h*.72,h*.48);cineFrame22(c,spriteInfo(23),0,w*.74,h*.72,h*.48);c.fillStyle='#07111be8';c.fillRect(0,h*.74,w,h*.26);cineText22(c,text23(mineIntroText25[part]),w,h*.8,Math.max(12,Math.min(18,h*.035)));}else{for(let n=0;n<22;n++){c.fillStyle=n%2?'#cbbe7444':'#87ef5544';c.fillRect((n*127+t*95)%w,(n*61-t*35+h*9)%h,4,14);}if(t<2)cineFrame22(c,spriteInfo(60),Math.floor(t*2)%4,w/2,h*.82,h*.65);else cineFrame22(c,spriteInfo(110),t<4?15+Math.floor(t*3)%3:t<6?12+Math.floor(t*3)%3:0,w/2,h*.84,h*.68);cineText22(c,'BENMOMIA',w,h*.12,Math.max(18,h*.06));}c.fillStyle='#040c0edc';c.fillRect(0,h-25,w,25);cineText22(c,text23(words23.skip),w,h-9,10);};
