if(q.mode===1){let dx=(!!q.keys.ArrowRight-!!q.keys.ArrowLeft)*125*dt,dy=(!!q.keys.ArrowDown-!!q.keys.ArrowUp)*125*dt;const solid=(x,y)=>x<16||x>624||y<32||y>404||q.walls.some(w=>x>w.x-10&&x<w.x+42&&y>w.y-10&&y<w.y+42);if(!solid(q.x+dx,q.y))q.x+=dx;if(!solid(q.x,q.y+dy))q.y+=dy;for(const w of q.walls){c.fillStyle='#7656a3';c.fillRect(w.x,w.y,30,30);}for(let i=q.pellets.length-1;i>=0;i--){const p=q.pellets[i];c.fillStyle='#89ffd2';c.fillRect(p.x-3,p.y-3,6,6);if(Math.hypot(p.x-q.x,p.y-q.y)<16){q.pellets.splice(i,1);q.score++;}}miniActor51(c,260,Math.floor(q.t*7)%3,q.x,q.y+16,30);for(let i=0;i<3;i++){const x=100+(q.t*(35+i*7)+i*150)%440,y=80+i*110;miniActor51(c,262,1,x,y,34);if(Math.hypot(x-q.x,y-15-q.y)<18){q.x=48;q.y=48;}}win=!q.pellets.length;}
