if(q.mode===3){q.x=clamp(q.x+(!!q.keys.ArrowRight-!!q.keys.ArrowLeft)*280*dt,20,620);q.cool-=dt;if(q.keys[' ']&&q.cool<=0){q.cool=.22;q.shots.push({x:q.x,y:350});}for(const d of q.drones)if(d.alive){const x=d.x+Math.sin(q.t*1.2)*25,y=d.y+q.t*4;miniActor51(c,262,1,x,y,42);for(const s of q.shots)if(Math.abs(s.x-x)<25&&Math.abs(s.y-y+20)<25){d.alive=false;s.y=-999;q.score++;}if(y>350)lose=true;}for(const s of q.shots){s.y-=350*dt;c.fillStyle='#89ff75';c.fillRect(s.x-2,s.y,4,12);}q.shots=q.shots.filter(s=>s.y>0);miniActor51(c,21,1,q.x,405,45);win=q.score===12;}
