function tileFloor75(c,x,y,right,bottom){if(right<=x||bottom<=y)return;const phase=(Math.floor(x/32)+Math.floor(y/32))%3;let pattern=floorPatterns75.get(phase);if(!pattern){const tile=document.createElement('canvas');tile.width=tile.height=96;const t=tile.getContext('2d');for(let j=0;j<3;j++)for(let i=0;i<3;i++){t.fillStyle=['#4c3071','#57377c','#613c83'][(i+j+phase)%3];t.fillRect(i*32+1,j*32+1,30,30);t.fillStyle='#8052a3';t.fillRect(i*32+3,j*32+2,24,2);}pattern=c.createPattern(tile,'repeat');floorPatterns75.set(phase,pattern);}c.save();c.translate(x,y);c.fillStyle=pattern;c.fillRect(0,0,Math.ceil((right-x)/32)*32,Math.ceil((bottom-y)/32)*32);c.restore();}
