// OMNIBLIZZ 0.93: official progression, independent Ten training and Order quests.
const ONLINE93='https://omniblizz-online93.ventisca.chatgpt.site';
const TRAIN93=['vitality','resistance','potency'];
function training93(o=player){const t=o.training93||{};const out={vitality:0,resistance:0,potency:0};let remaining=Math.min(6,Math.max(0,Math.floor(((Number(o.level)||1)-70)/5)));for(const k of TRAIN93){out[k]=Math.min(remaining,3,Math.max(0,Math.floor(Number(t[k])||0)));remaining-=out[k];}return out;}
function earned93(){return Math.min(6,Math.max(0,Math.floor((player.level-70)/5)));}
