const stateBefore125=local121;local121=function(o=player){const tier=o.fusion121?.tier,s=stateBefore125(o);if(tier===3)s.tier=3;for(const k of NEW_PARTS125)s.parts[k]=clamp(Math.floor(Number(s.parts[k])||0),0,999);s.seen125=!!s.seen125;return s;};
